import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig, ApiError } from 'lib/api'
import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'

import * as api from '../generated/api'
import type { BusinessKnowledgeSettingsApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeSettingsLogicValues {
    settings: BusinessKnowledgeSettingsApi | null
    settingsLoading: boolean
    settingsSaving: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeSettingsLogicActions {
    loadSettings: () => any
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: BusinessKnowledgeSettingsApi,
        payload?: any
    ) => {
        settings: BusinessKnowledgeSettingsApi
        payload?: any
    }
    setLearnFromSupportEnabled: (enabled: boolean) => {
        enabled: boolean
    }
}

export type businessKnowledgeSettingsLogicType = MakeLogicType<
    businessKnowledgeSettingsLogicValues,
    businessKnowledgeSettingsLogicActions
>

export const businessKnowledgeSettingsLogic = kea<businessKnowledgeSettingsLogicType>([
    path(['products', 'business_knowledge', 'frontend', 'settings', 'businessKnowledgeSettingsLogic']),
    actions({
        setLearnFromSupportEnabled: (enabled: boolean) => ({ enabled }),
    }),
    loaders(() => ({
        settings: [
            null as BusinessKnowledgeSettingsApi | null,
            {
                loadSettings: async () =>
                    await api.businessKnowledgeSettingsRetrieve(String(ApiConfig.getCurrentTeamId())),
            },
        ],
    })),
    reducers({
        settings: {
            setLearnFromSupportEnabled: (
                state: BusinessKnowledgeSettingsApi | null,
                { enabled }: { enabled: boolean }
            ): BusinessKnowledgeSettingsApi | null =>
                state ? { ...state, learn_from_support_enabled: enabled } : state,
        },
        settingsSaving: [
            false,
            {
                setLearnFromSupportEnabled: () => true,
                loadSettingsSuccess: () => false,
                loadSettingsFailure: () => false,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        setLearnFromSupportEnabled: async ({ enabled }) => {
            // Reducers run first, so `values.settings` is already the optimistic value.
            const previous =
                values.settings == null ? null : { ...values.settings, learn_from_support_enabled: !enabled }
            try {
                const updated = await api.businessKnowledgeSettingsPartialUpdate(String(ApiConfig.getCurrentTeamId()), {
                    learn_from_support_enabled: enabled,
                })
                actions.loadSettingsSuccess(updated)
            } catch (error) {
                if (previous) {
                    actions.loadSettingsSuccess(previous)
                }
                actions.loadSettings()
                lemonToast.error(
                    (error instanceof ApiError && error.detail) || 'Could not change the setting. Try again.'
                )
            }
        },
    })),
    afterMount(({ actions, values }) => {
        if (!values.settings) {
            actions.loadSettings()
        }
    }),
])
